/**
 * Copies a curated set of E2E screenshots into docs/screenshots/ for use in
 * the README and other documentation.
 *
 * Source: tests/screenshots/   (generated by the Playwright E2E suite)
 * Dest:   docs/screenshots/    (committed, rendered by GitHub)
 *
 * Run standalone:  node scripts/update-screenshots.js
 * Also called by:  npm run setup  (after E2E tests complete)
 */
import { copyFile, mkdir } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const SRC  = resolve(ROOT, 'tests', 'screenshots');
const DEST = resolve(ROOT, 'docs', 'screenshots');

const SCREENSHOTS = [
  // [source filename,                  dest filename]

  // Setup wizard
  ['01-welcome.png',                    '01-setup-welcome.png'],
  ['02-mascot.png',                     '02-setup-mascot.png'],

  // Core pages
  ['06-dashboard.png',                  '03-dashboard.png'],
  ['income-03-source-added.png',        '04-income.png'],
  ['accounts-03-added.png',             '05-accounts.png'],
  ['expenses-03-expense-added.png',     '06-expenses.png'],
  ['calendar-01-landing.png',           '07-calendar.png'],
  ['budget-04-with-chart.png',          '08-budget.png'],
  ['debt-02-card-added.png',            '09-debt.png'],
  ['reports-03-page-loaded.png',        '10-reports.png'],
  ['settings-01-page.png',             '11-settings.png'],

  // Import wizard — full step sequence
  ['import-02-step1.png',               '12-import-step1.png'],
  ['import-04-step2.png',               '13-import-step2.png'],
  ['import-04b-step3-progress.png',     '14-import-step3.png'],
  ['import-05-step4.png',               '15-import-step4.png'],
  ['import-07-ledger.png',              '16-import-ledger.png'],

  // Snapshots
  ['snap-02-snapshot-taken.png',        '17-snapshots.png'],

  // Bill tracking
  ['bills-03-past-due-badge.png',       '18-bills-status.png'],
  ['bills-05a-mark-paid-modal.png',     '19-bills-mark-paid.png'],

  // Bill cost thresholds
  ['threshold-04-overage-warning.png',  '20-threshold-overage.png'],

  // Debt — payment flow
  ['dp-04-pay-modal.png',               '21-debt-pay-modal.png'],
  ['dp-06-history-expanded.png',        '22-debt-pay-history.png'],

  // Budget — bucket editor
  ['buckets-03-editor-modal.png',       '23-budget-bucket-editor.png'],

  // Break Glass
  ['bg-03-warning-overlay.png',         '24-break-glass-warning.png'],
  ['bg-04-page-loaded.png',             '25-break-glass-browser.png'],
  ['bg-07-field-editor.png',            '26-break-glass-editor.png'],
  ['bg-15-orphan-detected.png',         '27-break-glass-orphan.png'],
];

async function main() {
  await mkdir(DEST, { recursive: true });

  let copied = 0;
  for (const [src, dest] of SCREENSHOTS) {
    await copyFile(resolve(SRC, src), resolve(DEST, dest));
    console.log(`  ✓ ${dest}`);
    copied++;
  }

  console.log(`\n✓ ${copied} screenshots copied to docs/screenshots/`);
}

main().catch(err => { console.error(err.message); process.exit(1); });
